-- drizzle cannot model: touch triggers, RLS policies, grants.
-- Sections (touch triggers, RLS) are the verbatim output of ../generate-platform-sql.ts.

-- touch-updated-at: generated by @seta/shared-db buildTouchUpdatedAtFnSql/buildTouchTriggerSql
CREATE OR REPLACE FUNCTION pm.tg_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END $$;
CREATE TRIGGER account_touch_updated_at
BEFORE UPDATE ON pm.account
FOR EACH ROW EXECUTE FUNCTION pm.tg_touch_updated_at();
CREATE TRIGGER project_touch_updated_at
BEFORE UPDATE ON pm.project
FOR EACH ROW EXECUTE FUNCTION pm.tg_touch_updated_at();
CREATE TRIGGER account_recruiter_touch_updated_at
BEFORE UPDATE ON pm.account_recruiter
FOR EACH ROW EXECUTE FUNCTION pm.tg_touch_updated_at();
CREATE TRIGGER allocation_touch_updated_at
BEFORE UPDATE ON pm.allocation
FOR EACH ROW EXECUTE FUNCTION pm.tg_touch_updated_at();
