BEFORE UPDATE ON pm.charter
FOR EACH ROW EXECUTE FUNCTION pm.tg_touch_updated_at();
CREATE TRIGGER project_access_touch_updated_at
BEFORE UPDATE ON pm.project_access
FOR EACH ROW EXECUTE FUNCTION pm.tg_touch_updated_at();
CREATE TRIGGER worker_projection_touch_updated_at
